From 7edbf44998f34b373b482cff723436b2d500a14c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:29:53 +0100
Subject: [PATCH] applets/systemtray: find icon theme paths inside Flatpak
 sandboxes

Flatpak apps such as Steam send an IconThemePath that only exists inside
their sandbox, so their tray icon was empty. When such a path is missing
on the host, look it up through the app's root in /proc instead.

BUG: 442153
---
 applets/systemtray/statusnotifieritemsource.cpp | 12 +++++++++---
 applets/systemtray/statusnotifieritemsource.h   |  1 +
 2 files changed, 10 insertions(+), 3 deletions(-)

diff --git a/applets/systemtray/statusnotifieritemsource.cpp b/applets/systemtray/statusnotifieritemsource.cpp
index eefedd6652..0269015521 100644
--- a/applets/systemtray/statusnotifieritemsource.cpp
+++ b/applets/systemtray/statusnotifieritemsource.cpp
@@ -124,6 +124,7 @@ StatusNotifierItemSource::StatusNotifierItemSource(const QString &notifierItemId
         m_flatpakInstance = instance;
         if (!instance.isEmpty()) {
             qCDebug(SYSTEM_TRAY) << "StatusNotifierItem" << notifierItemId << "is a flatpak" << instance;
+            m_flatpakRoot = "/proc/"_L1 + QString::number(pid.value()) + "/root"_L1;
         }
     }

@@ -324,9 +325,14 @@ void StatusNotifierItemSource::refreshCallback(QDBusPendingCallWatcher *call)
         // IconThemePath (handle this one first, because it has an impact on
         // others)
         QVariantMap properties = reply.argumentAt<0>();
-        QString path = properties[QStringLiteral("IconThemePath")].toString();
+        const QString themePath = properties[QStringLiteral("IconThemePath")].toString();

-        if (!path.isEmpty() && path != m_iconThemePath) {
+        if (!themePath.isEmpty() && themePath != m_iconThemePath) {
+            QString path = themePath;
+            // Paths sent by a flatpak may only exist inside its sandbox
+            if (!m_flatpakRoot.isEmpty() && !QFileInfo::exists(path) && QFileInfo::exists(m_flatpakRoot + path)) {
+                path = m_flatpakRoot + path;
+            }
             if (!m_customIconLoader) {
                 m_customIconLoader = new KIconLoader(QString(), QStringList(), this);
             }
@@ -349,7 +355,7 @@ void StatusNotifierItemSource::refreshCallback(QDBusPendingCallWatcher *call)
                 m_customIconLoader->addAppDir(appName.size() ? appName : QStringLiteral("unused"), path);
             });
         }
-        m_iconThemePath = path;
+        m_iconThemePath = themePath;

         m_category = properties[QStringLiteral("Category")].toString();
         m_status = properties[QStringLiteral("Status")].toString();
diff --git a/applets/systemtray/statusnotifieritemsource.h b/applets/systemtray/statusnotifieritemsource.h
index 8cf5258d72..a61b3afb02 100644
--- a/applets/systemtray/statusnotifieritemsource.h
+++ b/applets/systemtray/statusnotifieritemsource.h
@@ -96,4 +96,5 @@ private:
     QString m_toolTipTitle;
     QString m_windowId;
     QString m_flatpakInstance;
+    QString m_flatpakRoot;
 };
